-- SDKWork inventory consolidated initialization baseline (postgres)
-- Generated by reset-database-initialization-state.mjs
-- Application is in initialization state: full DDL lives here; migrations/ is reserved for post-GA changes.

-- baseline source: ddl/baseline/postgres/0001_inventory_baseline.sql
-- sdkwork:baseline
-- module: inventory
--
-- Inventory stock facts owned by the inventory capability. The catalog module
-- declares commerce_inventory_* as reference-only; the inventory module is the
-- physical owner of its stock table (column shape mirrors
-- crates/sdkwork-inventory-repository-sqlx/src/postgres_inventory.rs: text
-- ids, text timestamps, quantity counters).
CREATE TABLE IF NOT EXISTS commerce_inventory_stock (
    id TEXT NOT NULL PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    organization_id TEXT NOT NULL DEFAULT '0',
    shop_id TEXT,
    sku_id TEXT,
    warehouse_id TEXT,
    fulfillment_node_id TEXT,
    on_hand_quantity BIGINT NOT NULL DEFAULT 0,
    available_quantity BIGINT NOT NULL DEFAULT 0,
    locked_quantity BIGINT NOT NULL DEFAULT 0,
    reserved_quantity BIGINT NOT NULL DEFAULT 0,
    sold_quantity BIGINT NOT NULL DEFAULT 0,
    safety_stock_quantity BIGINT NOT NULL DEFAULT 0,
    version BIGINT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'active',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_commerce_inventory_stock_sku
    ON commerce_inventory_stock (tenant_id, sku_id, status);

-- Order-scoped reservation ledger consumed by the commerce order flow
-- (reserve at checkout, release/consume on cancel/fulfillment). Column shape
-- mirrors the physical-commerce integration tests:
-- crates/sdkwork-order-integration-physical-commerce/src/inventory/tests.rs.
CREATE TABLE IF NOT EXISTS commerce_inventory_reservation (
    id TEXT NOT NULL PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    organization_id TEXT NOT NULL DEFAULT '0',
    reservation_no TEXT NOT NULL,
    order_id TEXT NOT NULL,
    reservation_source_type TEXT NOT NULL,
    reservation_source_id TEXT NOT NULL,
    reservation_type TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    warehouse_id TEXT,
    fulfillment_node_id TEXT,
    quantity BIGINT NOT NULL DEFAULT 0,
    reserved_quantity BIGINT NOT NULL DEFAULT 0,
    consumed_quantity BIGINT NOT NULL DEFAULT 0,
    released_quantity BIGINT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'reserved',
    release_reason_code TEXT,
    request_no TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    consumed_at TEXT,
    released_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_commerce_inventory_reservation_order
    ON commerce_inventory_reservation (tenant_id, order_id);

-- folded migration: migrations/postgres/0001_organization_id_not_null.up.sql
-- sdkwork:migration
-- id: 0001_organization_id_not_null
-- engine: postgres
-- module: sdkwork-inventory
-- purpose: Enforce organization_id NOT NULL DEFAULT on all tables in the
--   consolidated baseline. NULL rows (pre-standard data anomalies) are
--   backfilled with the platform sentinel before NOT NULL is set, and
--   NOT NULL columns without an explicit default receive the sentinel
--   default, keeping existing deployments consistent with fresh baseline
--   installs.
-- reversible: false
-- rollback: forward-fix (sentinel backfill is the canonical fix; NULL
--   organization rows are data anomalies)
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

ALTER TABLE commerce_inventory_stock ADD COLUMN IF NOT EXISTS organization_id TEXT NOT NULL DEFAULT '0';
UPDATE commerce_inventory_stock SET organization_id = '0' WHERE organization_id IS NULL;
ALTER TABLE commerce_inventory_stock ALTER COLUMN organization_id SET DEFAULT '0';
ALTER TABLE commerce_inventory_stock ALTER COLUMN organization_id SET NOT NULL;

COMMIT;

-- folded migration: migrations/postgres/0002_inventory_movement_and_stock_quantities.up.sql
-- sdkwork:migration
-- id: 0002_inventory_movement_and_stock_quantities
-- engine: postgres
-- module: sdkwork-inventory
-- purpose: Materialize the append-only stock movement ledger the repository
--   already reads (commerce_inventory_movement) and add the inbound/damaged
--   quantity columns the merchant stock projections select. Both were missing
--   from the consolidated baseline, so listings and adjustments failed on a
--   freshly initialized database. Idempotent: safe to re-run on deployments
--   that already received the columns or table from a manual repair.
-- reversible: false
-- rollback: forward-fix (the ledger is additive; dropping it would destroy
--   stock history)
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

ALTER TABLE commerce_inventory_stock
    ADD COLUMN IF NOT EXISTS inbound_quantity BIGINT NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS damaged_quantity BIGINT NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS commerce_inventory_movement (
    id TEXT NOT NULL PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    organization_id TEXT NOT NULL DEFAULT '0',
    movement_no TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    warehouse_id TEXT,
    fulfillment_node_id TEXT,
    movement_type TEXT NOT NULL,
    source_type TEXT NOT NULL,
    quantity BIGINT NOT NULL DEFAULT 0,
    direction TEXT NOT NULL,
    quantity_before BIGINT NOT NULL DEFAULT 0,
    quantity_after BIGINT NOT NULL DEFAULT 0,
    business_type TEXT,
    source_id TEXT,
    reason TEXT,
    request_no TEXT,
    idempotency_key TEXT,
    occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_commerce_inventory_movement_tenant_sku
    ON commerce_inventory_movement (tenant_id, sku_id, occurred_at);

CREATE INDEX IF NOT EXISTS idx_commerce_inventory_movement_tenant_warehouse
    ON commerce_inventory_movement (tenant_id, warehouse_id, occurred_at);

COMMIT;
